// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    // fuzzed params: amount to send, and a boolean controlling whether the receiver reverts
    function testFuzz_property(uint256 amount, bool receiverReverts) public {
        // admissible domain: receiver must be non-zero and amount > 0 and not exceed contract balance
        vm.assume(amount > 0);

        // deploy adversarial receiver that optionally reverts on receive
        RevertingReceiver r = new RevertingReceiver(receiverReverts);

        // fund the contract so it can attempt the transfer
        vm.deal(address(c), amount);

        // call as the owner (deployer of C in setUp is this test contract) -> c's owner is address(this)
        // ensure msg.sender is owner by calling from this contract
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: The reference implementation (using transfer) will revert when the receiver reverts,
        // so for receiverReverts == true the call must NOT succeed (ok == false). The mutant (using unchecked send)
        // can return ok == true even when the receiver reverts. We assert the property that when the receiver is
        // configured to revert, the call does NOT succeed.
        if (receiverReverts) {
            assertTrue(!ok);
        } else {
            // when receiver does not revert, the call should succeed
            assertTrue(ok);
        }
    }
}

// adversarial receiver: either reverts on receive or accepts funds
contract RevertingReceiver {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable { shouldRevert = _shouldRevert; }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
}
